// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/internal/v1/resolve", wrapper.ResolveTenant)
	m.HandleFunc("GET "+options.BaseURL+"/v1/accounts", wrapper.ListAccounts)
	m.HandleFunc("POST "+options.BaseURL+"/v1/accounts", wrapper.CreateAccount)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/accounts/{accountId}", wrapper.DeleteAccount)
	m.HandleFunc("GET "+options.BaseURL+"/v1/accounts/{accountId}", wrapper.GetAccount)
	m.HandleFunc("GET "+options.BaseURL+"/v1/accounts/{accountId}/credentials", wrapper.ListCredentials)
	m.HandleFunc("POST "+options.BaseURL+"/v1/accounts/{accountId}/credentials", wrapper.CreateCredential)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/accounts/{accountId}/credentials/{keyId}", wrapper.RevokeCredential)
	m.HandleFunc("GET "+options.BaseURL+"/v1/accounts/{accountId}/tenants", wrapper.ListTenants)
	m.HandleFunc("POST "+options.BaseURL+"/v1/auth/login", wrapper.LoginWithPassword)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/networks/{networkId}", wrapper.DeleteNetwork)
	m.HandleFunc("GET "+options.BaseURL+"/v1/networks/{networkId}", wrapper.GetNetwork)
	m.HandleFunc("GET "+options.BaseURL+"/v1/tenants/{tenantId}", wrapper.GetTenant)
	m.HandleFunc("GET "+options.BaseURL+"/v1/tenants/{tenantId}/networks", wrapper.ListNetworks)
	m.HandleFunc("POST "+options.BaseURL+"/v1/tenants/{tenantId}/networks", wrapper.CreateNetwork)

	return m
}

